css:
/* レンズ／地紙型：左辺が弧、右辺は画面外へ */
figure{width:calc(50vw + 80px);margin-right:calc(50% - 50vw);
       border-radius:50% 0 0 50%/50% 0 0 50%;overflow:hidden}
/* D字：右辺だけ完全な半円 */
.d{border-radius:24px 9999px 9999px 24px / 24px 50% 50% 24px;overflow:hidden}
.d img{width:100%;height:100%;object-fit:cover;object-position:left center} /* 弧側で被写体が削れる */
